CREATE TABLE workflow_scope_versions (
    run_id              TEXT NOT NULL REFERENCES workflow_runs(run_id) ON DELETE RESTRICT,
    scope_version       INTEGER NOT NULL,
    command_id          TEXT,
    actor_role          TEXT NOT NULL,
    actor_id            TEXT NOT NULL,
    reason              TEXT,
    write_scope_json    TEXT NOT NULL,
    manifest_sha256     TEXT,
    stopped_evidence_json TEXT NOT NULL,
    created_at          TEXT NOT NULL,
    PRIMARY KEY (run_id, scope_version),
    CHECK (actor_role IN ('host','lead','console','service','workflow','bridge'))
);
INSERT INTO "workflow_scope_versions" VALUES('00000000-0000-0000-0000-000000000002',1,NULL,'host','fixture-host','original submission','[]','c740b2995992b1d361fa189d4bdfeef0268f86fdac1cd0367e6c1db0130043ff','{"kind":"initial"}','2026-01-01T00:00:00.000Z');
