    ON events(json_extract(CASE WHEN json_valid(payload_json) THEN payload_json END, '$.buddyId'), seq)
    WHERE kind IN ('router.answered','router.no_answer');
CREATE INDEX events_router_claimed_idx
    ON events(json_extract(CASE WHEN json_valid(payload_json) THEN payload_json END, '$.buddyId'), seq)
    WHERE kind='router.claimed';
